import app from 'flarum/forum/app';
import RedirectToHomeAndOpenModalPage from './RedirectToHomeAndOpenModalPage';
export default class SignupPage extends RedirectToHomeAndOpenModalPage {
  createModal() {
    if (!app.session.user) {
      return () => flarum.reg.asyncModuleImport('flarum/forum/components/SignUpModal');
    }
  }
}
flarum.reg.add('fof-direct-links', 'forum/components/SignupPage', SignupPage);