import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';

/**
 * A modal to show, either a modal class or a callback returning a promise that
 * resolves to one (for lazy loaded modals).
 */

export default class RedirectToHomeAndOpenModalPage extends Page {
  oninit(vnode) {
    super.oninit(vnode);
    m.route.set('/');
    const modal = this.createModal();
    if (modal) {
      setTimeout(() => app.modal.show(modal), 1500);
    }
  }

  /**
   * Return the modal to show once we have redirected home, or nothing if no
   * modal should be shown.
   */
  createModal() {
    return;
  }
  view() {
    return m("div", null);
  }
}
flarum.reg.add('fof-direct-links', 'forum/components/RedirectToHomeAndOpenModalPage', RedirectToHomeAndOpenModalPage);